doorhatchgateoverhaul.definition:
{
	"file": "doorhatchgateoverhaul.json",
	"settings": [
		{ "type": "separator", "title": "Common limits" },
		{
			"type": "float",
			"code": "MaxAutoCloseSeconds",
			"ingui": "Longest auto-close delay (seconds)",
			"comment": "Upper bound for the auto-close delay a player can pick on a door. A limit, not a default — every door behaviour in this mod is opt-in per block.",
			"default": 120.0,
			"range": { "min": 1.0, "max": 600.0, "step": 1.0 }
		},
		{
			"type": "float",
			"code": "MaxAutoOpenRange",
			"ingui": "Largest auto-open radius (blocks)",
			"comment": "Upper bound for the auto-open trigger radius a player can pick.",
			"default": 10.0,
			"range": { "min": 1.0, "max": 32.0, "step": 0.5 }
		},
		{
			"type": "float",
			"code": "MaxSwingSeconds",
			"ingui": "Slowest allowed swing (seconds)",
			"comment": "Slowest swing a player can ask for; also the GUI slider maximum.",
			"default": 15.0,
			"range": { "min": 1.0, "max": 60.0, "step": 0.5 }
		},
		{
			"type": "float",
			"code": "CollisionFollowsAnimationAboveSeconds",
			"ingui": "Slow-door collision threshold (seconds)",
			"comment": "Doors that take longer than this to swing keep their collision boxes shut until the animation finishes, so a slow castle gate is genuinely blocked while still opening. Quicker doors keep the stock instant behaviour. 0 turns the feature off.",
			"default": 1.5,
			"range": { "min": 0.0, "max": 15.0, "step": 0.1 }
		},
		{ "type": "separator", "title": "Advanced", "collapsible": true },
		{
			"type": "float",
			"code": "MinSwingSeconds",
			"ingui": "Fastest allowed swing (seconds)",
			"comment": "Fastest swing a player can ask for.",
			"default": 0.1,
			"range": { "min": 0.05, "max": 2.0, "step": 0.05 }
		},
		{
			"type": "integer",
			"code": "TickIntervalMs",
			"ingui": "Server tick interval (ms)",
			"comment": "How often the server checks auto-close timers and auto-open proximity. Takes effect on next world load — the tick loop is registered at startup.",
			"default": 250,
			"range": { "min": 50, "max": 2000, "step": 50 }
		},
		{
			"type": "float",
			"code": "MaxEditDistance",
			"ingui": "Max edit distance (blocks)",
			"comment": "How far a player may be from a door and still edit it. Purely an anti-tamper bound; land claims and locks decide actual permission.",
			"default": 24.0,
			"range": { "min": 4.0, "max": 64.0, "step": 1.0 }
		},
		{
			"type": "float",
			"code": "EaseFullSeconds",
			"ingui": "Easing full-swing constant (seconds)",
			"comment": "Seconds an engine easing animation of speed 1.0 takes to effectively finish; converts between the seconds a player picks and engine speed. Raise it if slow doors visually lag behind their collision.",
			"default": 4.6,
			"range": { "min": 0.5, "max": 10.0, "step": 0.1 }
		}
	]
}

